#include <bits/stdc++.h>
using namespace std;

string in;
size_t pos_ = 0;

unsigned hex4(size_t at) { return stoul(in.substr(at, 4), nullptr, 16); }

// Decodes a JSON string (at its opening quote) into Unicode code points.
vector<unsigned> readString() {
    vector<unsigned> cps;
    pos_++;
    while (in[pos_] != '"') {
        unsigned char c = in[pos_];
        if (c == '\\') {
            char e = in[pos_ + 1];
            pos_ += 2;
            switch (e) {
                case 'b': cps.push_back(8); break;
                case 'f': cps.push_back(12); break;
                case 'n': cps.push_back(10); break;
                case 'r': cps.push_back(13); break;
                case 't': cps.push_back(9); break;
                case 'u': {
                    unsigned u = hex4(pos_);
                    pos_ += 4;
                    // Join a high surrogate with a following escaped low surrogate.
                    if (u >= 0xD800 && u < 0xDC00 && in.compare(pos_, 2, "\\u") == 0) {
                        unsigned lo = hex4(pos_ + 2);
                        if (lo >= 0xDC00 && lo < 0xE000) { u = 0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00); pos_ += 6; }
                    }
                    cps.push_back(u);
                    break;
                }
                default: cps.push_back((unsigned char)e);
            }
            continue;
        }
        unsigned cp; int len;
        if (c < 0x80) cp = c, len = 1;
        else if (c < 0xE0) cp = c & 0x1F, len = 2;
        else if (c < 0xF0) cp = c & 0x0F, len = 3;
        else cp = c & 0x07, len = 4;
        for (int i = 1; i < len; i++) cp = (cp << 6) | (in[pos_ + i] & 0x3F);
        pos_ += len;
        cps.push_back(cp);
    }
    pos_++;
    return cps;
}

void writeEscaped(string& out, unsigned cp) {
    static const char* hexd = "0123456789abcdef";
    auto u4 = [&](unsigned u) {
        out += "\\u";
        for (int s = 12; s >= 0; s -= 4) out += hexd[(u >> s) & 15];
    };
    switch (cp) {
        case '"': out += "\\\""; return;
        case '\\': out += "\\\\"; return;
        case 8: out += "\\b"; return;
        case 9: out += "\\t"; return;
        case 10: out += "\\n"; return;
        case 12: out += "\\f"; return;
        case 13: out += "\\r"; return;
    }
    if (cp >= 0x20 && cp < 0x7F) out += char(cp);
    else if (cp < 0x10000) u4(cp);
    else { cp -= 0x10000; u4(0xD800 + (cp >> 10)); u4(0xDC00 + (cp & 0x3FF)); }
}

int main() {
    char chunk[1 << 16];
    for (size_t got; (got = fread(chunk, 1, sizeof chunk, stdin)) > 0;) in.append(chunk, got);
    // Shape: [order, [code, ...]]: the string at depth 1 is order, strings at depth 2 are codes.
    vector<unsigned> order;
    vector<vector<unsigned>> codes;
    int depth = 0;
    while (pos_ < in.size()) {
        char c = in[pos_];
        if (c == '[') depth++, pos_++;
        else if (c == ']') depth--, pos_++;
        else if (c == '"') {
            if (depth == 1) order = readString();
            else codes.push_back(readString());
        } else pos_++;
    }
    unordered_map<unsigned, int> rank;
    for (size_t i = 0; i < order.size(); i++) rank[order[i]] = i;
    // Rank bytes make an ordinary byte-wise lexicographic key.
    vector<string> keys(codes.size());
    for (size_t i = 0; i < codes.size(); i++) {
        keys[i].resize(codes[i].size());
        for (size_t j = 0; j < codes[i].size(); j++) keys[i][j] = char(rank[codes[i][j]]);
    }
    vector<int> idx(codes.size());
    iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&](int a, int b) { return keys[a] < keys[b]; });
    string out = "[";
    for (size_t k = 0; k < idx.size(); k++) {
        if (k) out += ',';
        out += '"';
        for (unsigned cp : codes[idx[k]]) writeEscaped(out, cp);
        out += '"';
    }
    out += "]\n";
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static String in;
    static int pos = 0;

    // Decodes a JSON string (at its opening quote) into Unicode code points.
    static int[] readString() {
        StringBuilder sb = new StringBuilder();
        pos++;
        while (in.charAt(pos) != '"') {
            char c = in.charAt(pos);
            if (c == '\\') {
                char e = in.charAt(pos + 1);
                pos += 2;
                switch (e) {
                    case 'b' -> sb.append('\b');
                    case 'f' -> sb.append('\f');
                    case 'n' -> sb.append('\n');
                    case 'r' -> sb.append('\r');
                    case 't' -> sb.append('\t');
                    case 'u' -> { sb.append((char) Integer.parseInt(in.substring(pos, pos + 4), 16)); pos += 4; }
                    default -> sb.append(e);
                }
            } else {
                sb.append(c);
                pos++;
            }
        }
        pos++;
        // Surrogate pairs (escaped or raw) become single code points here.
        return sb.toString().codePoints().toArray();
    }

    static final char[] HEX = "0123456789abcdef".toCharArray();

    static void u4(StringBuilder out, int u) {
        out.append("\\u");
        for (int s = 12; s >= 0; s -= 4) out.append(HEX[(u >> s) & 15]);
    }

    static void writeEscaped(StringBuilder out, int cp) {
        switch (cp) {
            case '"' -> out.append("\\\"");
            case '\\' -> out.append("\\\\");
            case 8 -> out.append("\\b");
            case 9 -> out.append("\\t");
            case 10 -> out.append("\\n");
            case 12 -> out.append("\\f");
            case 13 -> out.append("\\r");
            default -> {
                if (cp >= 0x20 && cp < 0x7F) out.append((char) cp);
                else if (cp < 0x10000) u4(out, cp);
                else { int v = cp - 0x10000; u4(out, 0xD800 + (v >> 10)); u4(out, 0xDC00 + (v & 0x3FF)); }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        in = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        // Shape: [order, [code, ...]]: the string at depth 1 is order, strings at depth 2 are codes.
        int[] order = new int[0];
        ArrayList<int[]> codes = new ArrayList<>();
        int depth = 0;
        while (pos < in.length()) {
            char c = in.charAt(pos);
            if (c == '[') { depth++; pos++; }
            else if (c == ']') { depth--; pos++; }
            else if (c == '"') {
                if (depth == 1) order = readString();
                else codes.add(readString());
            } else pos++;
        }
        HashMap<Integer, Integer> rank = new HashMap<>();
        for (int i = 0; i < order.length; i++) rank.put(order[i], i);
        int n = codes.size();
        // Rank bytes make an ordinary byte-wise lexicographic key (compared unsigned).
        byte[][] keys = new byte[n][];
        for (int i = 0; i < n; i++) {
            int[] code = codes.get(i);
            keys[i] = new byte[code.length];
            for (int j = 0; j < code.length; j++) keys[i][j] = (byte) (int) rank.get(code[j]);
        }
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Arrays.compareUnsigned(keys[a], keys[b]));
        StringBuilder out = new StringBuilder("[");
        for (int k = 0; k < n; k++) {
            if (k > 0) out.append(',');
            out.append('"');
            for (int cp : codes.get(idx[k])) writeEscaped(out, cp);
            out.append('"');
        }
        out.append("]\n");
        PrintStream ps = new PrintStream(new BufferedOutputStream(System.out, 1 << 16), false, StandardCharsets.US_ASCII);
        ps.print(out);
        ps.flush();
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"sort"
	"strconv"
	"unicode/utf8"
)

var in []byte
var pos int

func hex4(at int) rune {
	v, _ := strconv.ParseUint(string(in[at:at+4]), 16, 32)
	return rune(v)
}

// readString decodes a JSON string (at its opening quote) into Unicode code points.
func readString() []rune {
	cps := []rune{}
	pos++
	for in[pos] != '"' {
		c := in[pos]
		if c == '\\' {
			e := in[pos+1]
			pos += 2
			switch e {
			case 'b':
				cps = append(cps, 8)
			case 'f':
				cps = append(cps, 12)
			case 'n':
				cps = append(cps, 10)
			case 'r':
				cps = append(cps, 13)
			case 't':
				cps = append(cps, 9)
			case 'u':
				u := hex4(pos)
				pos += 4
				// Join a high surrogate with a following escaped low surrogate.
				if u >= 0xD800 && u < 0xDC00 && pos+6 <= len(in) && in[pos] == '\\' && in[pos+1] == 'u' {
					if lo := hex4(pos + 2); lo >= 0xDC00 && lo < 0xE000 {
						u = 0x10000 + (u-0xD800)<<10 + (lo - 0xDC00)
						pos += 6
					}
				}
				cps = append(cps, u)
			default:
				cps = append(cps, rune(e))
			}
			continue
		}
		r, size := utf8.DecodeRune(in[pos:])
		pos += size
		cps = append(cps, r)
	}
	pos++
	return cps
}

const hexd = "0123456789abcdef"

func u4(out []byte, u rune) []byte {
	out = append(out, '\\', 'u')
	for s := 12; s >= 0; s -= 4 {
		out = append(out, hexd[(u>>s)&15])
	}
	return out
}

func writeEscaped(out []byte, cp rune) []byte {
	switch cp {
	case '"':
		return append(out, '\\', '"')
	case '\\':
		return append(out, '\\', '\\')
	case 8:
		return append(out, '\\', 'b')
	case 9:
		return append(out, '\\', 't')
	case 10:
		return append(out, '\\', 'n')
	case 12:
		return append(out, '\\', 'f')
	case 13:
		return append(out, '\\', 'r')
	}
	if cp >= 0x20 && cp < 0x7F {
		return append(out, byte(cp))
	}
	if cp < 0x10000 {
		return u4(out, cp)
	}
	cp -= 0x10000
	out = u4(out, 0xD800+(cp>>10))
	return u4(out, 0xDC00+(cp&0x3FF))
}

func main() {
	in, _ = io.ReadAll(os.Stdin)
	// Shape: [order, [code, ...]]: the string at depth 1 is order, strings at depth 2 are codes.
	var order []rune
	codes := [][]rune{}
	depth := 0
	for pos < len(in) {
		switch in[pos] {
		case '[':
			depth++
			pos++
		case ']':
			depth--
			pos++
		case '"':
			if depth == 1 {
				order = readString()
			} else {
				codes = append(codes, readString())
			}
		default:
			pos++
		}
	}
	rank := map[rune]byte{}
	for i, r := range order {
		rank[r] = byte(i)
	}
	// Rank bytes make an ordinary byte-wise lexicographic key.
	keys := make([]string, len(codes))
	for i, code := range codes {
		key := make([]byte, len(code))
		for j, r := range code {
			key[j] = rank[r]
		}
		keys[i] = string(key)
	}
	idx := make([]int, len(codes))
	for i := range idx {
		idx[i] = i
	}
	sort.Slice(idx, func(a, b int) bool { return keys[idx[a]] < keys[idx[b]] })
	out := []byte{'['}
	for k, i := range idx {
		if k > 0 {
			out = append(out, ',')
		}
		out = append(out, '"')
		for _, cp := range codes[i] {
			out = writeEscaped(out, cp)
		}
		out = append(out, '"')
	}
	out = append(out, ']', '\n')
	w := bufio.NewWriter(os.Stdout)
	w.Write(out)
	w.Flush()
}
